133	  @Override
134	  public boolean tryLock(long time, TimeUnit unit) {
135	    LOG.info(generateLogStatement(LockState.ACQUIRING, generateLogSuffixString()));
136	    try {
137	      acquireLock(time, unit);
138	      LOG.info(generateLogStatement(LockState.ACQUIRED, generateLogSuffixString()));
139	    } catch (HoodieLockException e) {
140	      throw e;
141	    } catch (Exception e) {
142	      throw new HoodieLockException(generateLogStatement(LockState.FAILED_TO_ACQUIRE, generateLogSuffixString()), e);
143	    }
144	    return lock != null && lock.isAcquiredInThisProcess();
145	  }
146	
147	  @Override
148	  public void unlock() {
149	    try {
150	      LOG.info(generateLogStatement(LockState.RELEASING, generateLogSuffixString()));
151	      if (lock == null || !lock.isAcquiredInThisProcess()) {
152	        return;
153	      }
154	      lock.release();
155	      lock = null;
156	      LOG.info(generateLogStatement(LockState.RELEASED, generateLogSuffixString()));
157	    } catch (Exception e) {
158	      throw new HoodieLockException(generateLogStatement(LockState.FAILED_TO_RELEASE, generateLogSuffixString()), e);
159	    }
160	  }
