47	public class TestZookeeperBasedLockProvider {
48	
49	  private static final Logger LOG = LoggerFactory.getLogger(TestZookeeperBasedLockProvider.class);
50	
51	  private static TestingServer server;
52	  private static CuratorFramework client;
53	  private static String basePath = "/hudi/test/lock";
54	  private static String key = "table1";
55	  private static LockConfiguration lockConfiguration;
56	
57	  @BeforeAll
58	  public static void setup() {
59	    while (server == null) {
60	      try {
61	        server = new TestingServer();
62	        CuratorFrameworkFactory.Builder builder = CuratorFrameworkFactory.builder();
63	        client = builder.connectString(server.getConnectString()).retryPolicy(new RetryOneTime(1000)).build();
64	      } catch (Exception e) {
65	        LOG.error("Getting bind exception - retrying to allocate server");
66	        server = null;
67	      }
68	    }
69	    Properties properties = new Properties();
70	    properties.setProperty(ZK_BASE_PATH_PROP_KEY, basePath);
71	    properties.setProperty(ZK_LOCK_KEY_PROP_KEY, key);
72	    properties.setProperty(ZK_CONNECT_URL_PROP_KEY, server.getConnectString());
73	    properties.setProperty(ZK_BASE_PATH_PROP_KEY, server.getTempDirectory().getAbsolutePath());
74	    properties.setProperty(ZK_SESSION_TIMEOUT_MS_PROP_KEY, "10000");
75	    properties.setProperty(ZK_CONNECTION_TIMEOUT_MS_PROP_KEY, "10000");
76	    properties.setProperty(ZK_LOCK_KEY_PROP_KEY, "key");
77	    properties.setProperty(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY, "1000");
78	    lockConfiguration = new LockConfiguration(properties);
79	  }
80	
81	  @AfterAll
82	  public static void tearDown() throws IOException {
83	    if (server != null) {
84	      server.close();
85	    }
86	    if (client != null) {
87	      client.close();
88	    }
89	  }
90	
91	  @Test
92	  public void testAcquireLock() {
93	    ZookeeperBasedLockProvider zookeeperBasedLockProvider = new ZookeeperBasedLockProvider(lockConfiguration, client);
94	    Assertions.assertTrue(zookeeperBasedLockProvider.tryLock(lockConfiguration.getConfig()
95	        .getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS));
96	    zookeeperBasedLockProvider.unlock();
97	  }
98	
99	  @Test
100	  public void testUnLock() {
101	    ZookeeperBasedLockProvider zookeeperBasedLockProvider = new ZookeeperBasedLockProvider(lockConfiguration, client);
102	    Assertions.assertTrue(zookeeperBasedLockProvider.tryLock(lockConfiguration.getConfig()
103	        .getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS));
104	    zookeeperBasedLockProvider.unlock();
105	    zookeeperBasedLockProvider.tryLock(lockConfiguration.getConfig()
106	        .getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS);
107	  }
108	
109	  @Test
110	  public void testReentrantLock() {
111	    ZookeeperBasedLockProvider zookeeperBasedLockProvider = new ZookeeperBasedLockProvider(lockConfiguration, client);
112	    Assertions.assertTrue(zookeeperBasedLockProvider.tryLock(lockConfiguration.getConfig()
113	        .getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS));
114	    try {
115	      zookeeperBasedLockProvider.tryLock(lockConfiguration.getConfig()
116	          .getLong(LOCK_ACQUIRE_WAIT_TIMEOUT_MS_PROP_KEY), TimeUnit.MILLISECONDS);
117	      Assertions.fail();
118	    } catch (HoodieLockException e) {
119	      // expected
120	    }
121	    zookeeperBasedLockProvider.unlock();
122	  }
123	
124	  @Test
125	  public void testUnlockWithoutLock() {
126	    ZookeeperBasedLockProvider zookeeperBasedLockProvider = new ZookeeperBasedLockProvider(lockConfiguration, client);
127	    zookeeperBasedLockProvider.unlock();
128	  }
129	}
