51	/**
52	 * A zookeeper based lock. This {@link LockProvider} implementation allows to lock table operations
53	 * using zookeeper. Users need to have a Zookeeper cluster deployed to be able to use this lock.
54	 */
55	@NotThreadSafe
56	@Slf4j
57	public abstract class BaseZookeeperBasedLockProvider implements LockProvider<InterProcessMutex>, Serializable {
58	
59	  private final transient CuratorFramework curatorFrameworkClient;
60	  @Getter
61	  private volatile InterProcessMutex lock = null;
62	  protected final LockConfiguration lockConfiguration;
63	  protected final String zkBasePath;
64	  protected final String lockKey;
65	
66	  public BaseZookeeperBasedLockProvider(final LockConfiguration lockConfiguration, final StorageConfiguration<?> conf) {
67	    checkRequiredProps(lockConfiguration);
68	    this.lockConfiguration = lockConfiguration;
69	    zkBasePath = getZkBasePath(lockConfiguration);
70	    lockKey = getLockKey(lockConfiguration);
71	    int connectionTimeoutMs = ConfigUtils.getIntWithAltKeys(lockConfiguration.getConfig(), ZK_CONNECTION_TIMEOUT_MS);
72	    this.curatorFrameworkClient = CuratorFrameworkFactory.builder()
73	        .connectString(ConfigUtils.getStringWithAltKeys(lockConfiguration.getConfig(), ZK_CONNECT_URL))
74	        .retryPolicy(new BoundedExponentialBackoffRetry(
75	            ConfigUtils.getIntWithAltKeys(lockConfiguration.getConfig(), LOCK_ACQUIRE_RETRY_WAIT_TIME_IN_MILLIS),
76	            ConfigUtils.getIntWithAltKeys(lockConfiguration.getConfig(), LOCK_ACQUIRE_RETRY_MAX_WAIT_TIME_IN_MILLIS),
77	            ConfigUtils.getIntWithAltKeys(lockConfiguration.getConfig(), LOCK_ACQUIRE_NUM_RETRIES)))
78	        .sessionTimeoutMs(ConfigUtils.getIntWithAltKeys(lockConfiguration.getConfig(), ZK_SESSION_TIMEOUT_MS))
79	        .connectionTimeoutMs(connectionTimeoutMs)
80	        .build();
81	    this.curatorFrameworkClient.start();
82	    // Once started, the Curator client owns background threads. If anything below throws, the
83	    // constructor never returns the instance, so the caller can never invoke close() - clean up here.
84	    try {
85	      if (!this.curatorFrameworkClient.blockUntilConnected(connectionTimeoutMs, TimeUnit.MILLISECONDS)) {
